// Session-only local-file adaptation of MIT Feature Foundry MediaSurfaceController.
// Lifecycle/event patterns reuse Athena media/audio workspaces without depending on them.
export function attachNativeLocalVideo({host,signal,createVideo=()=>host.ownerDocument.createElement('video'),createURL=file=>URL.createObjectURL(file),revokeURL=url=>URL.revokeObjectURL(url)}){
 const doc=host.ownerDocument;let disposed=false,generation=0,playAttempt=0,active=null,state='empty',cleanupFailed=false;
 host.innerHTML='<h2>Local video surface</h2><p>Choose a local video explicitly. Session only: no upload, provider request, saved path or automatic playback. Browser codec support is not assumed.</p><label>Choose local video <input type="file" accept="video/*" data-local-video-file></label><button data-local-video-play disabled>Play selected video</button><button data-local-video-pause disabled>Pause</button><button data-local-video-close disabled>Close and release video</button><p data-local-video-name></p><p role="status" data-local-video-status>No video selected.</p><div data-local-video-view></div>';
 const one=q=>host.querySelector(q),input=one('[data-local-video-file]'),view=one('[data-local-video-view]'),status=one('[data-local-video-status]'),name=one('[data-local-video-name]'),play=one('[data-local-video-play]'),pause=one('[data-local-video-pause]'),close=one('[data-local-video-close]');
 const set=(value,message)=>{state=value;status.dataset.state=value;status.textContent=message};
 function release(){generation++;playAttempt++;const old=active;active=null;state='empty';if(old){for(const [type,fn] of old.listeners)old.video.removeEventListener(type,fn);try{old.video.pause()}catch{cleanupFailed=true}try{old.video.removeAttribute('src');old.video.load()}catch{cleanupFailed=true}try{revokeURL(old.url)}catch{cleanupFailed=true}old.video.remove()}view.replaceChildren();name.textContent='';play.disabled=pause.disabled=close.disabled=true;input.value='';host.dataset.localVideoCleanup=cleanupFailed?'unverified':'released';}
 function select(){if(disposed)return;const file=input.files?.[0];input.value='';if(!file)return;if(typeof file.type!=='string'||!file.type.startsWith('video/')||!Number.isFinite(file.size)||file.size<=0){status.textContent='Selection rejected: choose a nonempty video file. Previous video retained.';return}
  let video,url;try{video=createVideo();url=createURL(file)}catch{status.textContent='Could not prepare the selected local file. Previous video retained.';return}
  release();const token=generation,entry={video,url,listeners:[]};active=entry;video.controls=true;video.autoplay=false;video.loop=false;video.playsInline=true;video.preload='metadata';video.setAttribute('aria-label','Selected local video; session only');video.style.maxWidth='100%';name.textContent=file.name;set('selected','Local file selected. Metadata and playback not yet verified.');close.disabled=false;pause.disabled=false;
  const labels={loadedmetadata:['metadata-ready','Metadata received. Playback not verified.'],canplay:['canplay','Browser reports video can play. Press Play; playback not yet verified.'],playing:['playing','Native playing event observed.'],pause:['paused','Video paused.'],ended:['ended','Video ended.'],waiting:['buffering','Waiting for media data; not currently verified playing.'],stalled:['stalled','Media stalled; not currently verified playing.'],error:['failed','Browser could not play this local file. Codec support is not established.']};
  for(const [type,[value,message]] of Object.entries(labels)){const fn=e=>{if(disposed||active!==entry||token!==generation||e.isTrusted!==true)return;if(['pause','ended','error'].includes(type))playAttempt++;set(value,message);if(type==='canplay'||type==='loadedmetadata')play.disabled=false;if(type==='error')play.disabled=true};entry.listeners.push([type,fn]);video.addEventListener(type,fn)}
  try{view.append(video);video.src=url;video.load()}catch{release();set('failed','Could not load this local video. Resources released where supported; cleanup status is separately recorded.');}
 }
 async function requestPlay(){if(disposed||!active||play.disabled)return;const entry=active,token=generation,attempt=++playAttempt;set('play-requested','Playback requested; waiting for a native playing event.');try{await entry.video.play()}catch{if(!disposed&&active===entry&&token===generation&&attempt===playAttempt)set('play-rejected','Browser rejected playback. Use native controls or choose another video; no playback confirmed.')}}
 function requestPause(){if(disposed||!active)return;playAttempt++;try{active.video.pause()}catch{set('failed','Browser pause request failed. Close the video to release the source.')}}
 function clear(){release();set('empty',cleanupFailed?'Video closed. One or more cleanup operations failed; release is unverified.':'Video closed; session object URL released.');}
 input.addEventListener('change',select);play.addEventListener('click',requestPlay);pause.addEventListener('click',requestPause);close.addEventListener('click',clear);
 function dispose(){if(disposed)return;disposed=true;release();input.removeEventListener('change',select);play.removeEventListener('click',requestPlay);pause.removeEventListener('click',requestPause);close.removeEventListener('click',clear);signal?.removeEventListener('abort',dispose);host.replaceChildren()}
 signal?.addEventListener('abort',dispose,{once:true});if(signal?.aborted)dispose();return {dispose,getState:()=>({state,cleanup:cleanupFailed?'unverified':active?'in-use':'released'})};
}
